if P.exists() and any(P.iterdir()):
 raise SystemExit('Choose a new or empty directory; existing files will not be overwritten')
P.mkdir(parents=True,exist_ok=True)
def write(rel,rows,fields=None):
 p=P/rel;p.parent.mkdir(parents=True,exist_ok=True)
 if not fields:fields=list(rows[0])
 with p.open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(rows)
def js(rel,x):
 p=P/rel;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(x,indent=2)+'\n')
