def variant(id,path,mutate,checks,explanation,expected='',observed='',boundary=''):
 rows=copy.deepcopy(T[path]);mutate(rows);rel=f'variants/{id}/{Path(path).name}';write(rel,rows, list(T[path][0]))
 variants.append(dict(variant_id=id,base='clean',replacement_source=rel,replaces=path,expected_rule_ids=[x[0] for x in checks]))
 for rule,status in checks:findings.append(dict(variant_id=id,rule_id=rule,status=status,table=path,expected=expected,observed=observed,explanation=explanation,evidence_boundary=boundary or 'Requires declared schema, semantics and relevant supplied reference; expectations are minimum required findings, not exhaustive cascade counts'))
